package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class GH6400WriterTruncatedHeaderReviewTest {

	@TempDir
	Path directory;

	@Test
	void returnsUnknownSequenceForHeaderTruncatedInsideString() throws Exception {
		Path segment = directory.resolve("wal-2.v1");
		writeTruncatedHeader(segment);

		assertThat(ValueStoreWAL.readSegmentSequence(segment)).isZero();
	}

	@Test
	void returnsUnknownSequenceForHeaderTruncatedInsideUtf8Character() throws Exception {
		Path segment = directory.resolve("wal-2.v1");
		byte[] header = "{\"t\":\"V\",\"store\":\"é\",\"segment\":2}\n".getBytes(StandardCharsets.UTF_8);
		int bytesBeforeCrash = "{\"t\":\"V\",\"store\":\"".length() + 1;
		Files.write(segment, ByteBuffer.allocate(Integer.BYTES + bytesBeforeCrash)
				.order(ByteOrder.LITTLE_ENDIAN)
				.putInt(header.length)
				.put(header, 0, bytesBeforeCrash)
				.array());

		assertThat(ValueStoreWAL.readSegmentSequence(segment)).isZero();
	}

	@Test
	void reopensAfterCrashTruncatesNewSegmentHeader() throws Exception {
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(directory)
				.storeUuid("header-review")
				.syncPolicy(ValueStoreWalConfig.SyncPolicy.COMMIT)
				.build();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			long lsn = wal.logMint(1, ValueStoreWalValueKind.LITERAL, "durable", "", "", 0);
			wal.awaitDurable(lsn);
		}
		writeTruncatedHeader(directory.resolve("wal-2.v1"));

		try (ValueStoreWAL reopened = ValueStoreWAL.open(config)) {
			assertThat(reopened.hasInitialSegments()).isTrue();
		}
	}

	private static void writeTruncatedHeader(Path segment) throws Exception {
		byte[] header = ("{\"t\":\"V\",\"ver\":1,\"store\":\"header-review\",\"engine\":\"valuestore\","
				+ "\"created\":0,\"segment\":2,\"firstId\":2}\n").getBytes(StandardCharsets.UTF_8);
		int bytesBeforeCrash = "{\"t\":\"V\",\"ver\":1,\"store\":\"header".length();
		Files.write(segment, ByteBuffer.allocate(Integer.BYTES + bytesBeforeCrash)
				.order(ByteOrder.LITTLE_ENDIAN)
				.putInt(header.length)
				.put(header, 0, bytesBeforeCrash)
				.array());
	}
}
